#!/usr/bin/env python3
"""
Round 102b tiles patch (28 September 2026), beside round102b_culprits.py.

  scripts/christmas_trees.py   new, weekly: Christmas tree farms and sellers
                               worldwide from OpenStreetMap, merged with the
                               Real Christmas Tree Locator map (xmas/).

Whole files, written only where they differ. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/christmas_trees.py': ''}

changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if not p.parent.exists():
        raise SystemExit(f"round102b: {p.parent} not found; run from the culprits-tiles-more root")
    if p.exists() and p.read_bytes() == new:
        continue
    p.write_bytes(new)
    changed.append(path)
print("round102b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
